class StringUtils {
    private StringUtils() {}
    static boolean isEmpty(String s) { return s == null || s.isEmpty(); }
    static String capitalize(String s) {
        if (isEmpty(s)) return s;
        return Character.toUpperCase(s.charAt(0)) + s.substring(1);
    }
    static int countVowels(String s) {
        int count = 0;
        for (char c : s.toCharArray()) if ("aeiouAEIOU".indexOf(c) >= 0) count++;
        return count;
    }
}

public static void main(String[] args) {
    System.out.println(StringUtils.isEmpty(""));
    System.out.println(StringUtils.capitalize("java"));
    System.out.println(StringUtils.countVowels("programowanie"));
}

