class ArrayUtils {
    static int sum(int[] arr) { int s = 0; for (int x : arr) s += x; return s; }
    static double average(int[] arr) { return (double) sum(arr) / arr.length; }
    static int max(int[] arr) { int m = arr[0]; for (int x : arr) if (x > m) m = x; return m; }
    static int min(int[] arr) { int m = arr[0]; for (int x : arr) if (x < m) m = x; return m; }
}

public static void main(String[] args) {
    int[] data = {3, 7, 1, 9, 4, 6, 2};
    System.out.println(ArrayUtils.sum(data) + " " + ArrayUtils.average(data) + " " + ArrayUtils.max(data) + " " + ArrayUtils.min(data));
}

