class Fraction {
    final int numerator, denominator;
    private Fraction(int n, int d) { numerator = n; denominator = d; }
    static int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
    static Fraction of(int n, int d) { int g = gcd(Math.abs(n), Math.abs(d)); return new Fraction(n / g, d / g); }
    Fraction add(Fraction other) {
        return Fraction.of(numerator * other.denominator + other.numerator * denominator, denominator * other.denominator);
    }
    public String toString() { return numerator + "/" + denominator; }
}

public static void main(String[] args) {
    Fraction f = Fraction.of(6, 8);
    System.out.println(f); // 3/4
    System.out.println(f.add(Fraction.of(1, 4)));
}

