class ServiceLocator {
    static String[] names = new String[10];
    static Object[] services = new Object[10];
    static int size = 0;
    static void register(String name, Object service) { names[size] = name; services[size] = service; size++; }
    static Object get(String name) {
        for (int i = 0; i < size; i++) if (names[i].equals(name)) return services[i];
        return null;
    }
}

public static void main(String[] args) {
