import java.util.HashMap;
import java.util.Map;

class FontStyle {
    static Map<String, FontStyle> cache = new HashMap<>();
    boolean bold, italic; int size;
    private FontStyle(boolean b, boolean i, int s) { bold = b; italic = i; size = s; }
    static FontStyle getStyle(boolean b, boolean i, int size) {
        String key = b + "_" + i + "_" + size;
        return cache.computeIfAbsent(key, k -> new FontStyle(b, i, size));
    }
}

public static void main(String[] args) {
    FontStyle s1 = FontStyle.getStyle(true, false, 12);
    FontStyle s2 = FontStyle.getStyle(true, false, 12);
    System.out.println(s1 == s2); // true - ten sam obiekt z cache
}

