interface Service { void execute(String task); }
class RealService implements Service {
    public void execute(String task) { System.out.println("Wykonuje: " + task); }
}
class ServiceProxy implements Service {
    static int callCount = 0;
    RealService real = new RealService();
    public void execute(String task) {
        callCount++;
        System.out.println("[PROXY] wywolanie #" + callCount);
        real.execute(task);
    }
}

public static void main(String[] args) {
    Service s = new ServiceProxy();
    s.execute("Zadanie A");
    s.execute("Zadanie B");
}

