}

class ParentStatic { static void describe() { System.out.println("Jestem Parent"); } }
class ChildStatic extends ParentStatic { static void describe() { System.out.println("Jestem Child"); } }

public static void main(String[] args) {
    ParentStatic p = new ChildStatic();
    p.describe(); // "Jestem Parent" - static methods sa hidden, nie overridden, wiazanie po typie zmiennej (compile-time)
    // W przeciwienstwie do metod instancyjnych, ktore wiazane sa dynamicznie (runtime) wg rzeczywistego typu obiektu
}

