class ExpensiveResource {
    private static volatile ExpensiveResource instance;
    private ExpensiveResource() { System.out.println("Inicjalizacja..."); }
    static ExpensiveResource getInstance() {
        if (instance == null) {
            synchronized (ExpensiveResource.class) {
                if (instance == null) instance = new ExpensiveResource();
            }
        }
        return instance;
    }
}

public static void main(String[] args) {
    ExpensiveResource.getInstance();
    ExpensiveResource.getInstance();
    ExpensiveResource.getInstance(); // "Inicjalizacja..." wypisze sie tylko raz
}

class SQL {
    StringBuilder sb = new StringBuilder();
    static SQL select(String cols) { SQL s = new SQL(); s.sb.append("SELECT ").append(cols); return s; }
    SQL from(String table) { sb.append(" FROM ").append(table); return this; }
    SQL where(String cond) { sb.append(" WHERE ").append(cond); return this; }
    SQL orderBy(String col) { sb.append(" ORDER BY ").append(col); return this; }
    SQL limit(int n) { sb.append(" LIMIT ").append(n); return this; }
    String build() { return sb.toString(); }
}

public static void main(String[] args) {
    String query = SQL.select("name, age").from("users").where("age > 18").orderBy("name").limit(10).build();
    System.out.println(query);
}

